text:
{
  "jobs": [
    {
      "text": "Регулярно общаться с сыном, который живёт в другом районе",
      "quote": "Мы с мужем живём в другом районе, а с сыном почти каждый вечер разговариваем. Обычно он звонит по дороге с работы."
    },
    {
      "text": "Не беспокоить сына днём без необходимости",
      "quote": "Днём я его редко беспокою, поэтому, когда пару недель назад я сама набрала его после обеда, он сразу спросил, что случилось."
    },
    {
      "text": "Самостоятельно проверять подозрительные звонки от имени банка",
      "quote": "Он спросил, успела ли я назвать код, и подсказал посмотреть номер банка на обороте карты. Я сама туда дозвонилась."
    },
    {
      "text": "Сохранять нужные номера в телефоне",
      "quote": "А номер банка с той карты я теперь сохранила в телефоне."
    },
    {
      "text": "Делиться переживаниями с мужем",
      "quote": "Вечером рассказала мужу."
    },
    {
      "text": "Самостоятельно решать, что из произошедшего рассказывать близким",
      "quote": "Я хочу сама решать, что из этого рассказать."
    }
  ],
  "pains": [
    {
      "text": "Страх, что кредит оформляют на её имя",
      "quote": "Вдруг кто-то и правда берёт кредит на моё имя, а я бросила трубку посреди разговора с банком?"
    },
    {
      "text": "Сомнение и тревога после того, как положила трубку",
      "quote": "Тут я трубку положила. А сомнение осталось."
    },
    {
      "text": "Неловкость от необходимости оправдываться перед мошенником",
      "quote": "Мне было неловко даже сыну пересказывать, как я оправдывалась перед тем мужчиной за кредит, которого не брала."
    },
    {
      "text": "Пропущенный важный звонок из-за заглушения незнакомых номеров",
      "quote": "Пробовали ещё заглушать все незнакомые номера, но так я пропустила звонок из поликлиники о переносе приёма."
    },
    {
      "text": "Сбивает, когда на экране только номер без пояснений",
      "quote": "Меня сбивает, когда на экране просто номер и больше ничего."
    },
    {
      "text": "Ошибочное доверие к звонку, если телефон его «проверил»",
      "quote": "Я раньше думала, что телефон его проверил и всё в порядке."
    }
  ],
  "current_solutions": [
    {
      "text": "Определитель номера, установленный сыном",
      "quote": "Сын поставил нам обоим определитель."
    },
    {
      "text": "Заглушение всех незнакомых номеров (отказались)",
      "quote": "Пробовали ещё заглушать все незнакомые номера, но так я пропустила звонок из поликлиники о переносе приёма. Попросила [имя] вернуть звонки как было."
    },
    {
      "text": "Самостоятельный перезвон в банк по номеру с оборота карты",
      "quote": "Теперь, если представляются банком, я уже знаю, куда сама могу перезвонить."
    },
    {
      "text": "Звонок сыну в момент сомнения",
      "quote": "Вот с этим я [имя] и позвонила."
    }
  ],
  "barriers": [
    {
      "text": "Барьер понимания: неясно, как услуга распознаёт обман, если разговор уже идёт",
      "quote": "Мне только неясно, как услуга распознает обман, если я уже с человеком разговариваю."
    },
    {
      "text": "Барьер понимания: непонятно, что именно увидит сын",
      "quote": "Она слушает наш разговор? И что именно потом увидит сын?"
    },
    {
      "text": "Барьер выбора: решение зависит от примера сообщения сыну, а не от цены",
      "quote": "Только мне важно сначала увидеть пример сообщения, которое получит [имя]. От этого у меня решение зависит больше, чем от разницы в пятьдесят рублей."
    },
    {
      "text": "Барьер приватности: отказ от записи разговора сыну",
      "quote": "А если бы ему присылали запись разговора, я бы отказалась."
    }
  ],
  "triggers": [
    {
      "text": "Звонок от мужчины, представившегося по имени и отчеству, с вопросом о заявке на кредит",
      "quote": "Мне позвонил мужчина, обратился по имени и отчеству. Спросил, подавала ли я сегодня заявку на кредит."
    },
    {
      "text": "Просьба прочитать код из сообщения",
      "quote": "Он попросил прочитать код из сообщения."
    },
    {
      "text": "Оставшееся сомнение после того, как положила трубку",
      "quote": "А сомнение осталось."
    }
  ],
  "words": [
    "отпустило",
    "сбивает",
    "неловко",
    "оправдывалась",
    "беспокою",
    "дозвонилась",
    "перезвонить",
    "определитель",
    "заглушать",
    "представляются банком"
  ],
  "surprises": [
    "Готова платить около ста рублей в месяц за определитель, хотя сейчас за него отдельно не платит",
    "Готовность получать уведомления сыну о звонках мошенников сочетается с отказом от передачи записи разговора",
    "Решение о покупке зависит от примера сообщения сыну больше, чем от разницы в цене"
  ]
}
